// ============================================
// FILTER BADGE EARNED EVENTS
// ============================================

const items = $input.all();
const badgeEvents = [];

for (const item of items) {
  const data = item.json;

  // Parse event if stringified
  let event = data.event || data;
  if (typeof event === 'string') {
    try {
      event = JSON.parse(event);
    } catch (e) {
      continue;
    }
  }

  // Filter only badge:earned events
  if (event.event === 'badge:earned' || event.type === 'badge:earned') {
    badgeEvents.push({
      json: {
        event_id: data.id || `badge_${Date.now()}`,
        event_type: 'badge:earned',
        guild_id: event.guild_id,
        user_id: event.data?.user_id || event.user_id,
        discord_id: event.data?.discord_id || event.discord_id,
        badge_id: event.data?.badge_id,
        badge_name: event.data?.badge_name || 'Badge',
        badge_emoji: event.data?.badge_emoji || '🏅',
        badge_description: event.data?.badge_description || '',
        badge_rarity: event.data?.badge_rarity || 'common',
        timestamp: event.timestamp || new Date().toISOString()
      }
    });
  }
}

return badgeEvents.length > 0 ? badgeEvents : [];

// ============================================
// PREPARE BADGE EMBED
// ============================================

const data = $input.first().json;

// Rarity colors
const rarityColors = {
  common: 0x95A5A6,      // Gray
  uncommon: 0x2ECC71,    // Green
  rare: 0x3498DB,        // Blue
  epic: 0x9B59B6,        // Purple
  legendary: 0xF39C12,   // Orange
  mythic: 0xE74C3C       // Red
};

const rarityLabels = {
  common: 'Commun',
  uncommon: 'Peu commun',
  rare: 'Rare',
  epic: 'Épique',
  legendary: 'Légendaire',
  mythic: 'Mythique'
};

const color = rarityColors[data.badge_rarity] || 0x95A5A6;
const rarityLabel = rarityLabels[data.badge_rarity] || 'Commun';

const embed = {
  title: `${data.badge_emoji} Nouveau Badge Débloqué !`,
  description: `Tu as obtenu le badge **${data.badge_name}** !`,
  color: color,
  fields: [
    {
      name: '📋 Description',
      value: data.badge_description || 'Un badge spécial !',
      inline: false
    },
    {
      name: '💎 Rareté',
      value: rarityLabel,
      inline: true
    }
  ],
  footer: {
    text: 'Consulte ta collection avec /progression'
  },
  timestamp: data.timestamp
};

// Add thumbnail if badge has an image
if (data.badge_image_url) {
  embed.thumbnail = { url: data.badge_image_url };
}

// RFC-030: Format pour notifications:stream
return {
  type: 'dm',
  guild_id: data.guild_id,
  discord_id: data.discord_id,
  content: `<@${data.discord_id}> 🎊`,
  embed: embed,
  notification_type: 'badge_earned',
  source: 'n8n:NOTIF-Badge-Earned',
  event_id: data.event_id,
  timestamp: new Date().toISOString()
};

// ============================================
// LOG NOTIFICATION PUBLISHED
// ============================================

const response = $input.first().json;
const prepData = $('Prepare Notification Payload').first().json;

console.log(`Badge notification published to stream for user ${prepData.discord_id} in guild ${prepData.guild_id}`);

return {
  success: true,
  event_id: prepData.event_id,
  discord_id: prepData.discord_id,
  guild_id: prepData.guild_id,
  notification_type: 'badge_earned',
  stream: 'notifications:stream'
};
